    [
      {
        id: `${account.key}://SubFolder1`,
        accountId: account.key,
        name: "SubFolder1",
        path: "/SubFolder1",
        specialUse: [],
        isFavorite: false,
        isRoot: false,
        isTag: false,
        isUnified: false,
        isVirtual: false,
      },
    ],
    createData,
    "The onCreated event should return the correct values"
  );
}

